import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import static local.chuan.core.Protocol.*;

/** Chuan protocol 1 host. No Android dependencies: exercised against the Windows host on the JVM. */
public final class Engine implements Closeable {
    public static final String VERSION="2.0";
    static final long BROWSER_PRESENCE_GRACE=5*60*1000L;
    public static final class Config {
        public volatile String id=random(),name="Android 手机";
        public volatile int port=45871,discoveryPort=45872;
        public volatile boolean autoReceive=true,shareSoftware=true;
        public volatile long maxFiles,maxBytes;
        public File receiveDirectory,relayDirectory;
        public Config(File directory){receiveDirectory=directory;relayDirectory=new File(directory.getParentFile(),"relay");}
    }
    public interface Platform {
        InputStream asset(String name)throws IOException;
        File apk();
        String saved(Job job)throws IOException;
        void deleted(Job job)throws IOException;
        void settingsChanged(Config config);
    }
    public interface Opener {InputStream open()throws IOException;}
    public static final class Source {
        public final String path;public final long size;public final Opener opener;
        public Source(String path,long size,Opener opener){this.path=safePath(path);if(size<0)throw new IllegalArgumentException("文件长度未知");this.size=size;this.opener=opener;}
        public static Source file(File file,String path){return new Source(path,file.length(),()->new FileInputStream(file));}
    }
    public static final class Peer {
        public String id,name,ip,owner="",gateway="",instance="",platform="";public int port;public long seen;public boolean browser,reachable=true;
        public Peer(String id,String name,String ip,int port){this.id=id;this.name=name;this.ip=ip;this.port=port;seen=now();}
        Peer copy(){Peer peer=new Peer(id,name,ip,port);peer.owner=owner;peer.gateway=gateway;peer.instance=instance;peer.platform=platform;peer.browser=browser;peer.seen=seen;peer.reachable=reachable;return peer;}
    }
    public static final class Job {
        public final long id;public String name,peer,error="",activity="",resumeActivity="",webTab="",nativeOwner="",folderId="",folderName="",batchId="",owner="",recipient="",target="",upload="",displaySender="",publicUri="",stage="",storageKey="",asyncOfferKey="";
        public long total,done,folderTotal,folderCount,started=now(),finished;
        public int state,item;public double speed;public boolean receiving,requestOnly,awaitingApproval,staging,nativeHidden,removed;
        public volatile boolean cancelled;public boolean retryPending,announced,browserPaused;public String selection;public List<Item> offerItems=Collections.emptyList();
        public File file;public Source source;public List<Source> archiveSources=Collections.emptyList();final Set<Socket> sockets=ConcurrentHashMap.newKeySet();final Set<String> hiddenClients=new HashSet<>();
        long progressAt=now(),progressBytes;
        Job(long id,String name,String peer,long total,boolean receiving){this.id=id;this.name=name;this.peer=peer;this.total=total;this.receiving=receiving;}
    }
    public static final class Item {public String name;public boolean folder;public long count,total;Item(String name,boolean folder,long count,long total){this.name=name;this.folder=folder;this.count=count;this.total=total;}}
    static final class Session {
        String client,id,name="",token=random(),ip,platform="web";long ping,pingAt,ack,maxFiles,maxBytes;final Map<String,Long> tabs=new HashMap<>();final Set<String> openTabs=new HashSet<>();final Map<String,String> notes=new HashMap<>();
    }
    static final class Batch {
        String key,id,owner,target,recipient,selection="";boolean announced;final Set<Integer> cancelledItems=new HashSet<>(),announcedItems=new HashSet<>();List<Item> items;long touched=now();long[] counts,bytes;final Set<String> paths=new HashSet<>();final Map<Integer,File> roots=new HashMap<>();
    }
    final Object lock=new Object();public final Config config;public final String instance=random();final Platform platform;
    final Map<String,Peer> peers=new LinkedHashMap<>();final Map<Long,Job> jobs=new LinkedHashMap<>();final Map<String,Session> sessions=new LinkedHashMap<>();final Map<String,Batch> batches=new LinkedHashMap<>();
    final Map<String,Long> aliases=new LinkedHashMap<>();final Map<String,String> notes=new HashMap<>();long nextAlias=1,ping,pingAt;
    final AtomicLong nextJob=new AtomicLong(1);final Set<Socket> sockets=ConcurrentHashMap.newKeySet();
    final ExecutorService approvals=new ThreadPoolExecutor(0,12,30,TimeUnit.SECONDS,new SynchronousQueue<Runnable>());
    final ExecutorService sends=Executors.newFixedThreadPool(2);final ScheduledExecutorService scheduler=Executors.newScheduledThreadPool(2);
    final Transfers transfers;WebServer server;DatagramSocket discovery;volatile boolean running;volatile String notice="服务尚未开启";
    public Engine(Config config,Platform platform){this.config=config;this.platform=platform;transfers=new Transfers(this);}
    static long now(){return System.currentTimeMillis();}
    public void start()throws IOException {
        if(running)return;if(!config.receiveDirectory.isDirectory()&&!config.receiveDirectory.mkdirs())throw new IOException("无法创建接收目录");config.relayDirectory.mkdirs();
        String received=config.receiveDirectory.getCanonicalPath(),relay=config.relayDirectory.getCanonicalPath();if(received.equals(relay)||received.startsWith(relay+File.separator))throw new IOException("接收目录不能位于中转缓存中");purgeRelay(config.relayDirectory);
        server=new WebServer(this);server.start();config.port=server.port();running=true;
        try{discovery=new DatagramSocket(null);discovery.setReuseAddress(true);discovery.setBroadcast(true);discovery.bind(new InetSocketAddress(config.discoveryPort));discovery.setSoTimeout(800);Thread thread=new Thread(this::discover,"Chuan discovery");thread.setDaemon(true);thread.start();}catch(IOException error){if(discovery!=null)discovery.close();discovery=null;notice="广播不可用，可使用手动连接："+error.getMessage();}
        scheduler.scheduleWithFixedDelay(this::networkTick,0,2,TimeUnit.SECONDS);scheduler.scheduleWithFixedDelay(this::cleanRelay,60,60,TimeUnit.SECONDS);notice="局域网服务已开启";
    }
    public boolean running(){return running;}
    public void refresh(){announce();}
    public int port(){return config.port;}
    public List<String> addresses(){List<String> out=new ArrayList<>();try{for(NetworkInterface card:Collections.list(NetworkInterface.getNetworkInterfaces()))if(card.isUp()&&!card.isLoopback())for(InetAddress address:Collections.list(card.getInetAddresses()))if(address instanceof Inet4Address&&local(address.getHostAddress()))out.add(address.getHostAddress());}catch(Exception ignored){}return out;}
    static boolean local(String ip){try{InetAddress address=InetAddress.getByName(ip);return address instanceof Inet4Address&&(address.isSiteLocalAddress()||address.isLoopbackAddress()||address.isLinkLocalAddress());}catch(Exception error){return false;}}
    String alias(String id){Long value=aliases.get(id);if(value==null){value=nextAlias++;aliases.put(id,value);}return "A"+value;}
    void networkTick(){if(!running)return;try{
        announce();List<Peer> hosts=new ArrayList<>();synchronized(lock){expire();for(Peer peer:peers.values())if(!peer.browser)hosts.add(peer.copy());}
        for(Peer peer:hosts){if(!running)break;try{probe(peer.ip,peer.port);syncMesh(peer);}catch(Exception ignored){synchronized(lock){Peer current=peers.get(peer.id);if(current!=null&&now()-current.seen>6000)peers.remove(peer.id);}}}
    }catch(Exception error){notice="网络状态更新失败："+error.getMessage();}}
    void pauseBrowser(Job job,boolean paused,String message){if(paused&&!job.browserPaused){job.resumeActivity=job.activity;job.activity=message;job.browserPaused=true;}else if(!paused&&job.browserPaused){job.activity=job.resumeActivity;job.resumeActivity="";job.browserPaused=false;}}
    void expire(){long time=now();for(Session session:sessions.values()){session.tabs.entrySet().removeIf(tab->time-tab.getValue()>BROWSER_PRESENCE_GRACE);if(session.tabs.isEmpty())peers.remove(session.id);}peers.values().removeIf(peer->time-peer.seen>(peer.browser&&peer.owner.isEmpty()?BROWSER_PRESENCE_GRACE:7000));
        for(Job job:jobs.values())if(!job.asyncOfferKey.isEmpty()&&!job.nativeOwner.isEmpty()&&job.state<3){Batch batch=batches.get(job.asyncOfferKey);boolean live=peers.containsKey(unhex(job.nativeOwner));for(Job item:jobs.values())if(!item.requestOnly&&item.nativeOwner.equals(job.nativeOwner)&&item.batchId.equals(job.batchId)&&item.state==2)live=true;if(!live&&batch!=null&&time-batch.touched>45000){job.cancelled=true;transfers.completeOffer(job,Transfers.repeat('0',job.offerItems.size()));job.error="发送端已离线，接收请求已取消";}}
        for(Job job:jobs.values())if(job.announced&&job.state==0&&!job.owner.isEmpty()){Session sender=sessions.get(job.owner);if(sender==null||!sender.openTabs.contains(job.webTab)){job.announced=false;state(job,5,"发送页面已关闭，未收到此文件");}else pauseBrowser(job,sender.tabs.isEmpty(),"等待发送页面恢复");}
        for(Job job:jobs.values())if(!job.asyncOfferKey.isEmpty()&&!job.owner.isEmpty()&&job.state<3){Session sender=sessions.get(job.owner);if(sender==null||!sender.openTabs.contains(job.webTab)){job.cancelled=true;state(job,4,"发送页面已关闭，接收请求已取消");for(Socket socket:job.sockets)try{socket.close();}catch(IOException ignored){}}}
        for(Job job:jobs.values())if(!job.recipient.isEmpty()&&job.state==1){Session session=sessions.get(job.recipient);if(session==null||session.openTabs.isEmpty()){job.cancelled=true;state(job,4,"接收页面已关闭");}else pauseBrowser(job,session.tabs.isEmpty(),"等待接收页面恢复");}
        for(Job job:jobs.values())if(job.announced&&job.state==0&&!job.nativeOwner.isEmpty()){long touched=job.started;for(Batch batch:batches.values())if(batch.owner.equals(job.nativeOwner)&&batch.id.equals(job.batchId))touched=Math.max(touched,batch.touched);if(time-touched>45000){job.announced=false;state(job,5,"发送端已离线或停止，未收到 ZIP 文件");}} batches.values().removeIf(batch->batch.selection.indexOf('-')<0&&time-batch.touched>24*60*60*1000L);
        jobs.values().removeIf(job->job.state>=3&&(job.removed||job.nativeHidden&&job.asyncOfferKey.isEmpty()&&job.owner.isEmpty()&&job.recipient.isEmpty()));
    }
    void purgeRelay(File file){try{String root=config.relayDirectory.getCanonicalPath(),path=file.getCanonicalPath();if(!path.equals(root)&&!path.startsWith(root+File.separator))return;if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)purgeRelay(child);}if(!path.equals(root))file.delete();}catch(IOException ignored){}}
    void cleanRelay(){Map<File,List<Job>> files=new HashMap<>();Set<File> protectedFiles=new HashSet<>();synchronized(lock){for(Job job:jobs.values())if(job.staging&&job.file!=null){files.computeIfAbsent(job.file,key->new ArrayList<>()).add(job);if(job.state<3||job.finished==0||now()-job.finished<600000)protectedFiles.add(job.file);}}
        for(Map.Entry<File,List<Job>> entry:files.entrySet())if(!protectedFiles.contains(entry.getKey()))try{File file=entry.getKey();String root=config.relayDirectory.getCanonicalPath();if(file.getCanonicalPath().startsWith(root+File.separator)&&(!file.exists()||file.delete()))synchronized(lock){for(Job job:entry.getValue())job.removed=true;}}catch(IOException ignored){}
    }
    void announce(){if(discovery==null)return;byte[] ad=("CHUAN1|"+config.id+"|"+config.port+"|"+hex(config.name)).getBytes(StandardCharsets.UTF_8),query="CHUAN_DISCOVER1".getBytes(StandardCharsets.US_ASCII);Set<InetAddress> broadcasts=new HashSet<>();try{broadcasts.add(InetAddress.getByName("255.255.255.255"));for(NetworkInterface card:Collections.list(NetworkInterface.getNetworkInterfaces()))if(card.isUp()&&!card.isLoopback())for(InterfaceAddress address:card.getInterfaceAddresses())if(address.getBroadcast()!=null)broadcasts.add(address.getBroadcast());for(InetAddress address:broadcasts){discovery.send(new DatagramPacket(ad,ad.length,address,config.discoveryPort));discovery.send(new DatagramPacket(query,query.length,address,config.discoveryPort));}}catch(Exception ignored){}}
    void discover(){byte[] bytes=new byte[1400];while(running&&discovery!=null&&!discovery.isClosed())try{DatagramPacket packet=new DatagramPacket(bytes,bytes.length);discovery.receive(packet);String ip=packet.getAddress().getHostAddress();if(!local(ip))continue;String message=new String(bytes,0,packet.getLength(),StandardCharsets.UTF_8);if(message.equals("CHUAN_DISCOVER1")){byte[] reply=("CHUAN1|"+config.id+"|"+config.port+"|"+hex(config.name)).getBytes(StandardCharsets.UTF_8);discovery.send(new DatagramPacket(reply,reply.length,packet.getAddress(),packet.getPort()));continue;}String[] parts=message.split("\\|",4);if(parts.length!=4||!parts[0].equals("CHUAN1")||parts[1].equals(config.id)||parts[1].isEmpty()||parts[1].length()>64)continue;int port=Integer.parseInt(parts[2]);String name=unhex(parts[3]);if(port<1024||port>65535||name.length()>64)continue;synchronized(lock){if(peers.size()<128&&!peers.containsKey(parts[1])){Peer peer=new Peer(parts[1],name,ip,port);peer.reachable=false;peers.put(peer.id,peer);}}}catch(SocketTimeoutException ignored){}catch(Exception ignored){}}
    Map<String,String> identity(Peer peer){Map<String,String> headers=new LinkedHashMap<>();headers.put("X-Chuan-Id",hex(config.id));headers.put("X-Chuan-Sender",hex(config.name));headers.put("X-Chuan-Port",String.valueOf(config.port));headers.put("X-Chuan-Platform","android");if(peer!=null)headers.put("X-Chuan-Server",peer.owner.isEmpty()?peer.id:peer.owner);return headers;}
    String request(Peer peer,String method,String path,Map<String,String> extra,String body,int timeout)throws IOException {
        return request(peer,method,path,extra,body,timeout,null);
    }
    String request(Peer peer,String method,String path,Map<String,String> extra,String body,int timeout,Job control)throws IOException {
        return request(peer,method,path,extra,body,timeout,control,null);
    }
    String request(Peer peer,String method,String path,Map<String,String> extra,String body,int timeout,Job control,OutputStream waitingOutput)throws IOException {
        String address=peer.gateway.isEmpty()?peer.ip:peer.gateway;Socket socket=connect(address,peer.port,timeout);sockets.add(socket);if(control!=null)control.sockets.add(socket);try(Socket held=socket){
            Map<String,String> headers=identity(peer);headers.putAll(extra);byte[] payload=body.getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();StringBuilder request=new StringBuilder(method+" "+path+" HTTP/1.1\r\nHost: "+address+":"+peer.port+"\r\nConnection: close\r\nContent-Length: "+payload.length+"\r\n");for(Map.Entry<String,String> header:headers.entrySet())request.append(header.getKey()).append(": ").append(header.getValue()).append("\r\n");ascii(out,request+"\r\n");out.write(payload);out.flush();InputStream in=new BufferedInputStream(socket.getInputStream());Header result=header(in);while(result.status()==102){if(waitingOutput!=null)ascii(waitingOutput,"HTTP/1.1 102 Processing\r\n\r\n");result=header(in);}String answer=new String(read(in,result.length(),1048576),StandardCharsets.UTF_8);if(result.status()!=200&&!(path.equals("/api/offer")&&result.status()==202))throw new IOException(answer.isEmpty()?"设备响应 "+result.status():answer);return answer;
        }finally{sockets.remove(socket);if(control!=null)control.sockets.remove(socket);}
    }
    Socket connect(String address,int port,int timeout)throws IOException{if(!local(address))throw new IOException("目标地址不属于 IPv4 局域网");Socket socket=new Socket();socket.connect(new InetSocketAddress(address,port),4000);socket.setSoTimeout(timeout);socket.setTcpNoDelay(true);return socket;}
    Peer probe(String ip,int port)throws IOException {Peer address=new Peer("","",ip,port);String data=request(address,"GET","/api/info",Collections.emptyMap(),"",4000);Map<String,Object> info=Json.object(data);String id=Json.string(info,"id","");if(id.isEmpty()||id.length()>64||Json.number(info,"protocol",0)!=1)throw new IOException("目标不支持传输协议");if(id.equals(config.id))throw new IOException("不能连接本机");Peer peer=new Peer(id,unhex(Json.string(info,"nameHex","")),ip,(int)Json.number(info,"port",port));peer.instance=Json.string(info,"instance","");String kind=Json.string(info,"platform","");peer.platform=kind.equals("windows")||kind.equals("android")?kind:"";synchronized(lock){if(peers.size()<128||peers.containsKey(id))peers.put(id,peer);}return peer;}
    public void addPeer(String address){sends.execute(()->{try{String[] parts=address.trim().split(":");if(parts.length>2)throw new IOException("请输入 IPv4 地址和端口");probe(parts[0],parts.length==2?Integer.parseInt(parts[1]):45871);notice="设备已连接";}catch(Exception error){notice="连接失败："+error.getMessage();}});}
    void observe(Header header,String ip){try{String id=unhex(header.get("x-chuan-id")),name=unhex(header.get("x-chuan-sender"));int port=(int)number(header.get("x-chuan-port"));if(id.isEmpty()||id.equals(config.id)||id.startsWith("web:")||id.length()>64||name.length()>64||name.matches(".*[\\r\\n].*")||port<1024||port>65535)return;synchronized(lock){if(peers.size()<128||peers.containsKey(id)){Peer current=peers.get(id),next=new Peer(id,name.isEmpty()?alias(id):name,ip,port);String kind=header.get("x-chuan-platform");next.platform=kind.equals("windows")||kind.equals("android")?kind:current==null?"":current.platform;if(current!=null&&current.reachable&&current.port==port&&now()-current.seen<6000){next.ip=current.ip;next.instance=current.instance;}peers.put(id,next);}}}catch(Exception ignored){}}
    String leader(){String leader=config.id;for(Peer peer:peers.values())if(!peer.browser&&now()-peer.seen<6000&&peer.id.compareTo(leader)<0)leader=peer.id;return leader;}
    String mesh(String ledger){synchronized(lock){expire();for(String line:ledger.split("\n"))try{String[] fields=line.trim().split(" +");if(fields.length!=2)continue;String key=unhex(fields[0]);long value=number(fields[1]);if(key.isEmpty()||key.length()>128||value<=0||value>9007199254740991L||aliases.size()>=4096&&!aliases.containsKey(key))continue;if(!aliases.containsKey(key))aliases.put(key,aliases.containsValue(value)?nextAlias++:value);nextAlias=Math.max(nextAlias,aliases.get(key)+1);}catch(Exception ignored){}
        String leader=leader();if(leader.equals(config.id)){Set<Long> allocated=new HashSet<>();for(Map.Entry<String,Long> entry:aliases.entrySet())if(!allocated.add(entry.getValue())){entry.setValue(nextAlias++);allocated.add(entry.getValue());}}
        StringBuilder out=new StringBuilder("L "+hex(leader)+"\n");for(Map.Entry<String,Long> entry:aliases.entrySet())out.append("N ").append(hex(entry.getKey())).append(' ').append(entry.getValue()).append('\n');for(Session session:sessions.values())if(!session.tabs.isEmpty())out.append("B ").append(hex(session.id)).append(' ').append(hex(session.name)).append(' ').append(session.ip).append(' ').append(session.platform).append('\n');return out.toString();}}
    void syncMesh(Peer peer)throws IOException {StringBuilder ledger=new StringBuilder();synchronized(lock){for(Map.Entry<String,Long> entry:aliases.entrySet())ledger.append(hex(entry.getKey())).append(' ').append(entry.getValue()).append('\n');}String response=request(peer,"POST","/api/mesh",Collections.emptyMap(),ledger.toString(),4000);synchronized(lock){Set<String> live=new HashSet<>();String leader=leader();boolean authority=false;for(String line:response.split("\n"))try{String[] parts=line.split(" +");if(parts[0].equals("L")&&parts.length==2)authority=unhex(parts[1]).equals(leader)&&peer.id.equals(leader);
        else if(parts[0].equals("N")&&parts.length==3){String id=unhex(parts[1]);long value=number(parts[2]);if(!id.isEmpty()&&id.length()<=128&&value>0&&value<9007199254740991L&&(aliases.size()<4096||aliases.containsKey(id))){if(authority||!aliases.containsKey(id))aliases.put(id,value);nextAlias=Math.max(nextAlias,value+1);}}
        else if(parts[0].equals("B")&&parts.length>=4&&parts.length<=5&&local(parts[3])){String id=unhex(parts[1]),name=unhex(parts[2]);if(!id.startsWith("web:")||id.length()>128||name.length()>64||name.indexOf('\r')>=0||name.indexOf('\n')>=0)continue;Peer browser=new Peer(id,name,parts[3],peer.port);browser.browser=true;browser.platform=parts.length==5&&(parts[4].equals("mobile-web")||parts[4].equals("desktop-web"))?parts[4]:"web";browser.owner=peer.id;browser.gateway=peer.ip;Peer old=peers.get(id);if((old==null&&peers.size()<256)||old!=null&&old.owner.equals(peer.id)){peers.put(id,browser);live.add(id);}}
        }catch(Exception ignored){}peers.values().removeIf(item->item.owner.equals(peer.id)&&!live.contains(item.id));}}
    Peer peer(String id)throws IOException {synchronized(lock){Peer peer=peers.get(id);if(peer==null||now()-peer.seen>(peer.browser&&peer.owner.isEmpty()?BROWSER_PRESENCE_GRACE:7500))throw new IOException("目标设备已离线");return peer.copy();}}
    Job job(String name,String peer,long total,boolean receiving)throws IOException {synchronized(lock){if(jobs.size()>=4096)throw new IOException("任务数量达到上限，请清理已结束记录");Job job=new Job(nextJob.getAndIncrement(),name,peer,total,receiving);jobs.put(job.id,job);return job;}}
    void state(Job job,int state,String error){synchronized(lock){if(state==2&&job.state!=2){job.started=now();job.progressAt=job.started;job.progressBytes=0;}job.state=state;job.error=error;if(state>=3)job.finished=now();job.awaitingApproval=false;lock.notifyAll();}}
    void progress(Job job,long bytes)throws IOException {if(job.cancelled||!running)throw new IOException("传输已取消");synchronized(lock){job.done=bytes;long time=now();if(time-job.progressAt>=150){job.speed=(bytes-job.progressBytes)*1000.0/Math.max(1,time-job.progressAt);job.progressAt=time;job.progressBytes=bytes;}}}
    public void send(String target,List<Source> files){try{Peer peer=peer(target);sends.execute(()->transfers.send(peer,files));}catch(Exception error){notice=error.getMessage();}}
    public void retry(long id){try{
        final List<Source> files=new ArrayList<>();final Job selected;final Peer target;
        synchronized(lock){selected=jobs.get(id);if(selected==null||selected.receiving||!selected.owner.isEmpty()||selected.source==null||selected.state<4||selected.retryPending)throw new IOException("此发送记录暂时无法重试");target=peer(selected.target);
            for(Job job:jobs.values())if(job.target.equals(selected.target)&&job.source!=null&&job.state<3&&(job.source==selected.source||!selected.folderId.isEmpty()&&job.folderName.equals(selected.folderName)))throw new IOException("此项目已有进行中的发送任务");
            for(Job job:jobs.values())if(job.id==id||!selected.folderId.isEmpty()&&job.folderId.equals(selected.folderId)&&job.batchId.equals(selected.batchId)){if(!job.archiveSources.isEmpty())files.addAll(job.archiveSources);else if(job.source!=null)files.add(job.source);}
            selected.retryPending=true;
        }
        sends.execute(()->{try{transfers.send(target,files);}finally{synchronized(lock){selected.retryPending=false;}}});
    }catch(Exception error){notice="重试失败："+error.getMessage();}}
    public void decide(long id,String selection){synchronized(lock){Job job=jobs.get(id);if(job==null||!job.awaitingApproval||!selection.matches("[01-]+")||selection.length()!=job.offerItems.size())return;
        if(!job.asyncOfferKey.isEmpty())transfers.completeOffer(job,selection);
        else {String previous=job.selection==null?Transfers.repeat('-',selection.length()):job.selection;StringBuilder merged=new StringBuilder(previous);for(int i=0;i<selection.length();i++)if(previous.charAt(i)=='-'&&selection.charAt(i)!='-')merged.setCharAt(i,selection.charAt(i));job.selection=merged.toString();job.awaitingApproval=job.selection.indexOf('-')>=0;}lock.notifyAll();}}
    public void cancel(long id){synchronized(lock){Job selected=jobs.get(id);if(selected==null)return;for(Job job:jobs.values())if(job.id==id||(!selected.folderId.isEmpty()&&selected.folderId.equals(job.folderId)&&selected.folderName.equals(job.folderName)&&selected.batchId.equals(job.batchId)&&selected.owner.equals(job.owner)&&selected.recipient.equals(job.recipient)&&selected.receiving==job.receiving&&selected.peer.equals(job.peer))){if(job.state>=3)continue;job.cancelled=true;job.announced=false;state(job,4,job.receiving?"接收端已取消本次传输":"发送已取消");if(!job.owner.isEmpty()||!job.nativeOwner.isEmpty())for(Batch batch:batches.values())if(batch.key.endsWith(":"+(job.owner.isEmpty()?job.nativeOwner:job.owner)+":"+job.batchId))batch.cancelledItems.add(job.item);for(Socket socket:job.sockets)try{socket.close();}catch(IOException ignored){}}lock.notifyAll();}}
    public void clear(){synchronized(lock){for(Job job:jobs.values())if(job.state>=3)job.nativeHidden=true;}}
    public void delete(long id){sends.execute(()->{Job selected;synchronized(lock){selected=jobs.get(id);}if(selected==null||selected.state<3)return;List<Job> removed=new ArrayList<>();synchronized(lock){for(Job job:jobs.values())if(job.id==id||(!selected.folderId.isEmpty()&&job.folderId.equals(selected.folderId)&&job.folderName.equals(selected.folderName)&&job.batchId.equals(selected.batchId)&&job.owner.equals(selected.owner)&&job.recipient.equals(selected.recipient)&&job.receiving==selected.receiving&&job.peer.equals(selected.peer)))removed.add(job);}for(Job job:removed)try{if(job.receiving&&!job.staging){platform.deleted(job);if(job.file!=null&&job.file.exists()&&!job.file.delete())throw new IOException("无法删除接收文件");}synchronized(lock){job.removed=true;job.nativeHidden=true;}}catch(Exception error){notice="删除失败："+error.getMessage();}});}
    public void note(String ip,String value){if(value.length()>48||value.matches(".*[\\r\\n].*"))return;synchronized(lock){notes.put(ip,value);}}
    public void ping(String target){sends.execute(()->{try{pingNow(peer(target));notice="Ping 已送达";}catch(Exception error){notice="Ping 失败："+error.getMessage();}});}
    void pingNow(Peer peer)throws IOException {if(peer.browser&&peer.owner.isEmpty()){Session selected=null;long sequence;synchronized(lock){for(Session session:sessions.values())if(session.id.equals(peer.id)&&!session.tabs.isEmpty())selected=session;if(selected==null)throw new IOException("浏览器已离线");sequence=++selected.ping;selected.pingAt=now();}long deadline=now()+3500;while(now()<deadline&&running){synchronized(lock){if(selected.ack>=sequence)return;}try{Thread.sleep(40);}catch(InterruptedException error){Thread.currentThread().interrupt();throw new IOException(error);}}throw new IOException("浏览器未确认");}request(peer,"POST","/api/ping",Collections.singletonMap("X-Chuan-Target",hex(peer.id)),"",4500);}
    public void configure(String name,boolean autoReceive,boolean share,long maxFiles,long maxBytes){if(name.trim().isEmpty()||name.length()>64||name.matches(".*[\\r\\n|].*")||maxFiles<0||maxBytes<0)throw new IllegalArgumentException("设置参数无效");synchronized(lock){config.name=name.trim();config.autoReceive=autoReceive;config.shareSoftware=share;config.maxFiles=maxFiles;config.maxBytes=maxBytes;}platform.settingsChanged(config);announce();}
    public Job find(long id){synchronized(lock){return jobs.get(id);}}
    public static String stateText(int state){return new String[]{"等待发送","等待接收","传输中","已完成","已取消","传输失败","已拒绝"}[Math.max(0,Math.min(6,state))];}
    Map<String,Object> itemJson(Item item){return Json.map("name",item.name,"folder",item.folder,"count",String.valueOf(item.count),"total",String.valueOf(item.total));}
    Map<String,Object> jobJson(Job job,Session session){boolean own=session!=null&&job.owner.equals(session.client),recipient=session!=null&&job.recipient.equals(session.client);boolean receiving=recipient||(!own&&job.receiving);String remote=job.peer;if(own&&!job.target.isEmpty()){Peer target=peers.get(job.target);remote=job.target.equals(config.id)?config.name:target==null?"目标设备":target.name;}return Json.map("id",String.valueOf(job.id),"name",job.name,"peer",remote,"total",job.total,"done",job.done,"speed",job.state==2?job.speed:0,"state",job.state,"stateText",job.state<3&&!job.activity.isEmpty()?job.activity:job.state==1&&!receiving?"等待对方确认":stateText(job.state),"receiving",receiving,"target",job.target.isEmpty()?config.id:job.target,"canRetry",!receiving&&job.owner.isEmpty()&&job.source!=null&&job.state>=4&&!job.retryPending,"groupScope",job.storageKey,"batchId",job.batchId,"folderId",job.folderId,"folderName",job.folderName,"folderCount",job.folderCount,"folderTotal",job.folderTotal,"canDelete",own,"removed",job.removed,"uploadKey",own?job.upload:"","stage",own?job.stage:"","fileId",String.valueOf(job.id),"error",job.error,"publicUri",session==null?job.publicUri:"");}
    public Map<String,Object> snapshot(){synchronized(lock){expire();List<Object> peerList=new ArrayList<>(),jobList=new ArrayList<>(),requests=new ArrayList<>();for(Peer peer:peers.values())peerList.add(Json.map("id",peer.id,"name",peer.name,"ip",peer.ip,"port",peer.port,"browser",peer.browser,"platform",peer.platform,"owner",peer.owner,"note",notes.getOrDefault(peer.ip,"")));for(Job job:jobs.values()){if(job.awaitingApproval&&job.recipient.isEmpty()){List<Object> items=new ArrayList<>();for(Item item:job.offerItems)items.add(itemJson(item));requests.add(Json.map("id",job.id,"sender",job.peer,"selection",job.selection==null?"":job.selection,"items",items));}if(!job.requestOnly&&!job.nativeHidden&&!job.removed)jobList.add(jobJson(job,null));}return Json.map("id",config.id,"instance",instance,"version",VERSION,"name",config.name,"port",config.port,"addresses",addresses(),"running",running,"notice",notice,"autoReceive",config.autoReceive,"shareSoftware",config.shareSoftware,"maxFiles",config.maxFiles,"maxBytes",config.maxBytes,"directory",config.receiveDirectory.getAbsolutePath(),"peers",peerList,"jobs",jobList,"requests",requests,"ping",now()-pingAt<4000?ping:0);}}
    @Override public void close(){running=false;if(discovery!=null)discovery.close();if(server!=null)server.close();for(Socket socket:sockets)try{socket.close();}catch(IOException ignored){}synchronized(lock){for(Job job:jobs.values())if(job.state<3){job.cancelled=true;state(job,4,"服务已停止");}lock.notifyAll();}scheduler.shutdownNow();approvals.shutdownNow();sends.shutdownNow();purgeRelay(config.relayDirectory);notice="局域网服务已停止";}
}
